<script lang="ts">
 import {onMount,onDestroy,untrack} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import {openUrl} from '@tauri-apps/plugin-opener';
 import {Mail,Search,Inbox,Send,RefreshCw,Paperclip,ChevronRight,ArrowUpRight,PanelLeftOpen,PanelLeftClose,X,Download,ArrowUpRight as SentArrow,ArrowDownLeft,Flag} from 'lucide-svelte';
 import {canPreviewAttachment,addressLabel,addressFull,mailDate,mergeMail,mailConversations,outlookLink,attachmentPreview,type MailMessage,type MailAttachment,type MailPage} from './mail';
 import {inlineCid,imageApprovalKey} from './mail-images';
 import MailReadTimer from './MailReadTimer.svelte';
 import MailDetails from './MailDetails.svelte';
 import {safeMessageLink} from './message-body';
 import MailBody from './MailBody.svelte';
 import MailComposer from './MailComposer.svelte';
 import {draftKey,newMailDraft,responseDraft,restoreDrafts,type MailDraft} from './mail-drafts';
 import {signatureFor} from './mail-signature';
 import {removeMailFile} from './mail-attachments';
 import {fileSize} from './attachments';
 let {readDelay=0,detailsOpen=false,onDetails=()=>{},onDetailsAvailable=()=>{},ownId,ownMailAddresses=[],isLive,sidebarOpen,onSidebar,onSignIn,authBusy,onRecipientHandled=()=>{},initialRecipient='',initialDraft=null,initialMessage=null,defaultPresentation="html"}:{readDelay?:number;detailsOpen?:boolean;onDetails?:(open:boolean)=>void;onDetailsAvailable?:(available:boolean)=>void;ownId:string;ownMailAddresses?:string[];defaultPresentation?:"html"|"plain";onRecipientHandled?:()=>void;initialRecipient?:string;initialDraft?:MailDraft|null;initialMessage?:MailMessage|null;isLive:boolean;sidebarOpen:boolean;onSidebar:(open:boolean)=>void;onSignIn:()=>void;authBusy:boolean}=$props();
 let canWrite=$state(false),readBusy=$state(false),readError=$state(''),readMenu=$state<{x:number;y:number;messages:MailMessage[]}|null>(null),readHold=$state<Record<string,boolean>>({});
 let permitted=$state(false),checking=$state(true),folder=$state('inbox'),search=$state(''),applied=$state('');
 let rows=$state<MailMessage[]>([]),next=$state<string|null>(null),loading=$state(false),error=$state('');
 let selected=$state<MailMessage|null>(null),thread=$state<MailMessage[]>([]),threadNext=$state<string|null>(null),threadBusy=$state(false),threadError=$state('');
 let bodies=$state<Record<string,MailMessage>>({}),bodyBusy=$state<Record<string,boolean>>({}),bodyError=$state<Record<string,string>>({}),expanded=$state<Record<string,boolean>>({});
 let files=$state<Record<string,MailAttachment[]>>({}),fileNext=$state<Record<string,string|null>>({}),fileBusy=$state<Record<string,boolean>>({}),fileError=$state<Record<string,string>>({});
 let preview=$state<{name:string;image?:string;text?:string}|null>(null),saving=$state(false),fileNotice=$state('');
 let focused=$state(''),hashes=$state<Record<string,string>>({}),collecting=$state(false);let collectionKey='';
 let inlineImages=$state<Record<string,Record<string,string>>>({}),plainMessages=$state<Record<string,boolean>>({});
 let alive=true,listSerial=0,threadSerial=0;
 $effect(()=>{onDetailsAvailable(!!selected&&!activeDraft);});
 $effect(()=>{const key=detailsOpen&&!activeDraft&&selected?selected.id+':'+thread.map(m=>m.id).join(','):'';if(key&&key!==collectionKey){collectionKey=key;untrack(()=>{void collectMedia();});}});
 async function collectMedia(){if(collecting)return;const serial=threadSerial;collecting=true;try{const pending=thread.filter(m=>!bodies[m.id]||!files[m.id]);for(const m of pending.slice(0,25)){if(!alive||serial!==threadSerial)return;if(!bodies[m.id])await body(m.id);else await attachments(m.id);}}finally{if(alive&&serial===threadSerial)collecting=false;}}
 async function showMessage(id:string){const serial=threadSerial;focused=id;delete readHold[id];expanded[id]=true;await body(id);await new Promise(resolve=>requestAnimationFrame(resolve));if(!alive||serial!==threadSerial)return;document.getElementById('mail-message-'+id)?.scrollIntoView({block:'nearest',behavior:'smooth'});}

 const draftAccount=untrack(()=>ownId);
 let drafts=$state<MailDraft[]>([]),composing=$state(''),canSend=$state(false),draftNotice=$state('');
 const activeDraft=$derived(drafts.find(d=>d.id===composing));
 function saveDraft(d:MailDraft){
  try{const current=restoreDrafts(localStorage.getItem(draftKey(draftAccount)));const next=[d,...current.filter(row=>row.id!==d.id)];const serialized=JSON.stringify(next);if(next.length>20||new TextEncoder().encode(serialized).length>2000000)throw Error();localStorage.setItem(draftKey(draftAccount),serialized);drafts=next;draftNotice='';return true;}catch{draftNotice='Local draft storage is unavailable or full. Keep this window open and copy your text before leaving.';drafts=[d,...drafts.filter(row=>row.id!==d.id)];return false;}
 }
 function respond(id:string,action:'reply'|'replyAll'|'forward'){const original=bodies[id];if(!original)return;const existing=drafts.find(d=>d.sourceId===id&&d.action===action);if(existing){composing=existing.id;return;}const d={...responseDraft(original,action,ownMailAddresses),signature:signatureFor(draftAccount,action)};if(saveDraft(d))composing=d.id;}
 function newDraft(){const d={...newMailDraft(),signature:signatureFor(draftAccount)};saveDraft(d);composing=d.id;}
 function removeDraft(id:string){try{const stored=restoreDrafts(localStorage.getItem(draftKey(draftAccount)));const removed=stored.find(d=>d.id===id);const next=stored.filter(d=>d.id!==id);localStorage.setItem(draftKey(draftAccount),JSON.stringify(next));drafts=next;composing='';for(const file of removed?.attachments??[])void removeMailFile(draftAccount,id,file.id).catch(()=>{});return true;}catch{draftNotice='Draft could not be removed from local storage.';return false;}}
 let sentRefresh:ReturnType<typeof setTimeout>|undefined;
 function cancelSentRefresh(){clearTimeout(sentRefresh);sentRefresh=undefined;}
 function accepted(id:string){
  if(removeDraft(id))draftNotice='Accepted for sending by Microsoft 365. Delivery may take a moment. A copy is saved in Sent.';
  cancelSentRefresh();
  const serial=threadSerial;
  // Graph may accept the send before its Sent copy is available. Retry reads only.
  const refresh=async(attempt:number)=>{
   if(!alive||serial!==threadSerial||!selected?.conversationId)return;
   await loadThread(false,true);
   if(alive&&serial===threadSerial&&attempt<3)sentRefresh=setTimeout(()=>void refresh(attempt+1),[2000,5000,10000][attempt]);
  };
  void refresh(0);
 }

 const direction=(message:MailMessage)=>{const from=message.from?.emailAddress?.address?.toLowerCase();return ownMailAddresses.length&&from?(ownMailAddresses.some(a=>a.toLowerCase()===from)?'Sent':'Received'):'';};
 const conversations=$derived(mailConversations(rows));
 const query=()=>({collection:'messages',folder,search:applied||null});
 const page=<T,>(query:Record<string,unknown>)=>invoke<MailPage<T>>('mail_page',{query});
 async function start(){try{drafts=restoreDrafts(localStorage.getItem(draftKey(draftAccount)));}catch{draftNotice='Local draft storage is unavailable.';}void invoke<boolean>('mail_write_permission').then(value=>{if(alive)canWrite=value;}).catch(()=>{});void invoke<boolean>('mail_send_permission').then(value=>{if(alive)canSend=value;}).catch(()=>{});checking=true;error='';try{const allowed=await invoke<boolean>('mail_permission');if(!alive)return;permitted=allowed;if(allowed){await load();if(alive&&initialMessage)await choose(initialMessage);if(alive&&initialDraft){const d={...initialDraft,signature:signatureFor(draftAccount)};if(saveDraft(d)){composing=d.id;onRecipientHandled();}}else if(alive&&initialRecipient){const d={...newMailDraft(),signature:signatureFor(draftAccount)};d.to=initialRecipient;if(saveDraft(d)){composing=d.id;onRecipientHandled();}}}}catch(e){if(alive)error=String(e);}finally{if(alive)checking=false;}}
 async function load(more=false){if(loading||!permitted)return;const serial=++listSerial;loading=true;error='';try{const result=await page<MailMessage>({...query(),next:more?next:null});if(!alive||serial!==listSerial)return;rows=more?mergeMail(rows,result.value):result.value;next=result.next;}catch(e){if(alive&&serial===listSerial)error=String(e);}finally{if(alive&&serial===listSerial)loading=false;}}
 async function folderChange(value:string){composing='';++listSerial;loading=false;folder=value;search='';applied='';rows=[];next=null;clearSelection();await load();}
 async function submitSearch(){if(search.trim()===applied&&rows.length)return;applied=search.trim();++listSerial;loading=false;rows=[];next=null;clearSelection();await load();}
 function clearSelection(){cancelSentRefresh();++threadSerial;readMenu=null;readHold={};focused='';hashes={};collecting=false;collectionKey='';inlineImages={};plainMessages={};selected=null;thread=[];threadNext=null;threadError='';threadBusy=false;bodies={};expanded={};bodyBusy={};bodyError={};files={};fileBusy={};fileError={};fileNext={};preview=null;fileNotice='';}
 async function choose(message:MailMessage){composing='';clearSelection();selected=message;focused=message.id;thread=[message];expanded={[message.id]:true};void body(message.id);if(message.conversationId)await loadThread();}
 async function loadThread(more=false,preserve=false){if(!selected?.conversationId||threadBusy)return;const serial=threadSerial;const selectedMessage=selected;threadBusy=true;threadError='';try{const result=await page<MailMessage>({collection:'conversation',conversationId:selectedMessage.conversationId,next:more?threadNext:null});if(!alive||serial!==threadSerial)return;thread=mergeMail(more||preserve?thread:[selectedMessage],result.value).sort((a,b)=>(a.receivedDateTime??a.sentDateTime??'').localeCompare(b.receivedDateTime??b.sentDateTime??''));if(!preserve)threadNext=result.next;}catch(e){if(alive&&serial===threadSerial)threadError=String(e);}finally{if(alive&&serial===threadSerial)threadBusy=false;}}
 async function body(id:string){if(bodyBusy[id]||bodies[id])return;const serial=threadSerial;bodyBusy[id]=true;bodyError[id]='';try{const message=await invoke<MailMessage>('mail_page',{query:{collection:'message',messageId:id}});if(alive&&serial===threadSerial){bodies[id]=message;await attachments(id);}}catch(e){if(alive&&serial===threadSerial)bodyError[id]=String(e);}finally{if(alive&&serial===threadSerial)bodyBusy[id]=false;}}
 function toggle(message:MailMessage){focused=message.id;expanded[message.id]=!expanded[message.id];if(expanded[message.id]){delete readHold[message.id];void body(message.id);}}
 async function attachments(id:string,more=false){if(fileBusy[id])return;const serial=threadSerial;fileBusy[id]=true;fileError[id]='';try{const result=await page<MailAttachment>({collection:'attachments',messageId:id,next:more?fileNext[id]:null});if(alive&&serial===threadSerial){files[id]=more?mergeMail(files[id]??[],result.value):result.value;fileNext[id]=result.next;for(const file of result.value.slice(0,10)){if(inlineCid(file,bodies[id]?.body?.content??'')&&localStorage.getItem(imageApprovalKey(ownId,id,file.id))==='true')void restoreImage(id,file,serial);}}}catch(e){if(alive&&serial===threadSerial)fileError[id]=String(e);}finally{if(alive&&serial===threadSerial)fileBusy[id]=false;}}
 async function restoreImage(id:string,file:MailAttachment,serial:number){try{const data=await invoke<{contentType:string;base64:string}>('mail_attachment',{messageId:id,attachmentId:file.id});const content=attachmentPreview(data);if(alive&&serial===threadSerial&&content.image&&localStorage.getItem(imageApprovalKey(ownId,id,file.id))==='true')inlineImages[id]={...inlineImages[id],[file.contentId!.replace(/^<|>$/g,'')]:content.image};}catch{if(alive&&serial===threadSerial)fileNotice='An approved image could not be loaded. Preview to try again.';}}
 function blockImage(id:string,file:MailAttachment){try{localStorage.removeItem(imageApprovalKey(ownId,id,file.id));}catch{fileNotice='Image approval could not be removed from local storage.';return;}const next={...inlineImages[id]};delete next[file.contentId!.replace(/^<|>$/g,'')];inlineImages[id]=next;}
 async function viewFile(id:string,file:MailAttachment){if(saving)return;const serial=threadSerial;saving=true;fileNotice='';try{const data=await invoke<{contentType:string;base64:string}>('mail_attachment',{messageId:id,attachmentId:file.id});if(!alive||serial!==threadSerial)return;const content=attachmentPreview(data);if(content.image){const bytes=Uint8Array.from(atob(data.base64),c=>c.charCodeAt(0));const digest=await crypto.subtle.digest('SHA-256',bytes);if(!alive||serial!==threadSerial)return;hashes[JSON.stringify([id,file.id])]=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');}if(content.image&&inlineCid(file,bodies[id]?.body?.content??'')&&!(plainMessages[id]??defaultPresentation==='plain')){localStorage.setItem(imageApprovalKey(ownId,id,file.id),'true');inlineImages[id]={...inlineImages[id],[inlineCid(file,bodies[id]?.body?.content??'')]:content.image};fileNotice='Inline image approved for this email. Use Block again to revoke.';}else if(content.image||content.text!==undefined)preview={name:file.name??'Attachment',...content};else fileNotice='Preview is unavailable for this file type. Save it or open the message in Outlook.';}catch(e){if(alive&&serial===threadSerial)fileNotice=String(e);}finally{if(alive)saving=false;}}
 async function saveFile(id:string,file:MailAttachment){if(saving)return;const serial=threadSerial;saving=true;fileNotice='';try{const saved=await invoke<boolean>('mail_save_attachment',{messageId:id,attachmentId:file.id});if(alive&&serial===threadSerial)fileNotice=saved?'Attachment saved.':'Save cancelled.';}catch(e){if(alive&&serial===threadSerial)fileNotice=String(e);}finally{if(alive)saving=false;}}
 function context(event:MouseEvent,messages:MailMessage[]){if(window.getSelection()?.toString())return;event.preventDefault();readMenu={x:Math.min(event.clientX,window.innerWidth-260),y:Math.min(event.clientY,window.innerHeight-140),messages};}
 async function setRead(messages:MailMessage[],read:boolean){if(readBusy||!canWrite)return;readMenu=null;readBusy=true;readError='';const serial=threadSerial;for(const m of messages)readHold[m.id]=true;
 try{for(const message of messages){const value=await invoke<{id:string;isRead:boolean}>('mail_set_read',{ownId,messageId:message.id,isRead:read});if(!alive)return;if(value.id!==message.id||value.isRead!==read)throw Error('Mail read state was not confirmed. Refresh before retrying.');rows=rows.map(m=>m.id===value.id?{...m,isRead:value.isRead}:m);if(serial===threadSerial){thread=thread.map(m=>m.id===value.id?{...m,isRead:value.isRead}:m);if(bodies[value.id])bodies[value.id]={...bodies[value.id],isRead:value.isRead};}}}catch(e){if(alive)readError=String(e);}finally{if(alive)readBusy=false;}
 }
 async function original(message:MailMessage){const url=outlookLink(message.webLink);if(url)try{await openUrl(url);}catch{fileNotice='Outlook could not be opened.';}}
 function menuFocus(node:HTMLElement){const previous=document.activeElement as HTMLElement|null;const buttons=()=>Array.from(node.querySelectorAll<HTMLButtonElement>('button:not(:disabled)'));buttons()[0]?.focus();const keys=(event:KeyboardEvent)=>{if(['ArrowDown','ArrowUp','Tab'].includes(event.key)){event.preventDefault();const list=buttons(),index=list.indexOf(document.activeElement as HTMLButtonElement);list[(index+(event.key==='ArrowUp'||event.shiftKey?-1:1)+list.length)%list.length]?.focus();}};node.addEventListener('keydown',keys);return {destroy(){node.removeEventListener('keydown',keys);if(previous?.isConnected)previous.focus();}};}
 function previewFocus(node:HTMLElement){const previous=document.activeElement as HTMLElement|null;const close=node.querySelector<HTMLButtonElement>('button');close?.focus();const keys=(event:KeyboardEvent)=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();preview=null;}else if(event.key==='Tab'){event.preventDefault();close?.focus();}};node.addEventListener('keydown',keys);return {destroy(){node.removeEventListener('keydown',keys);if(previous?.isConnected)previous.focus();}};}
 onMount(()=>{if(isLive)void start();else checking=false;});onDestroy(()=>{cancelSentRefresh();alive=false;onDetailsAvailable(false);++listSerial;++threadSerial;});
</script>
<div class="mail-workspace">
 {#if sidebarOpen}<aside class="mail-list" aria-label="Mail navigation"><header><div><span class="eyebrow">YOUR WORKSPACE</span><h1>Mail <small>PREVIEW</small></h1></div><button aria-label="Collapse mail sidebar" onclick={()=>onSidebar(false)}><PanelLeftClose size={18}/></button></header>
 <div class="mail-compose-actions"><button disabled={!isLive} onclick={newDraft}>New email</button><span>{drafts.length} local drafts</span></div>
 <div class="mail-folders" aria-label="Mail folders"><button class:chosen={folder==='inbox'&&!applied} disabled={!permitted} onclick={()=>folderChange('inbox')}><Inbox size={16}/>Inbox</button><button class:chosen={folder==='sentitems'&&!applied} disabled={!permitted} onclick={()=>folderChange('sentitems')}><Send size={16}/>Sent</button></div>
 <p class="folder-hint">Folder filters · conversations include both sides</p>
 <form class="mail-search" onsubmit={e=>{e.preventDefault();void submitSearch();}}><Search size={16}/><input aria-label="Search mailbox" placeholder="Search your mailbox" bind:value={search} maxlength="500" disabled={!permitted}/>{#if search||applied}<button type="button" aria-label="Clear mailbox search" onclick={()=>folderChange(folder)}><X size={16}/></button>{/if}<button aria-label="Search mail" disabled={!permitted||loading}><ChevronRight size={16}/></button></form>
 <div class="mail-list-heading"><span>{applied?'MAILBOX SEARCH':folder==='inbox'?'INBOX':'SENT MAIL'} · {conversations.length} conversations · {rows.length} messages loaded</span><button aria-label="Refresh mail" disabled={!permitted||loading} onclick={()=>load()}><RefreshCw size={15}/></button></div>
 {#if applied}<div class="mail-search-hint">Results for “{applied}” across your mailbox.<button onclick={()=>folderChange(folder)}>Clear search</button></div>{/if}
 {#if error}<p role="alert" class="mail-error">{error}<button disabled={loading} onclick={()=>permitted?load():start()}>Try again</button></p>{/if}
 <div class="mail-rows" aria-label="Mail messages">{#if drafts.length}<details class="local-drafts"><summary>Drafts on this Mac ({drafts.length})</summary>{#each drafts as draft(draft.id)}<button class="mail-row" onclick={()=>composing=draft.id}><strong>{draft.subject||'Untitled draft'}</strong><small>{draft.to||'No recipients yet'}{draft.uncertain?' · Check sending status':''}</small></button>{/each}</details>{/if}{#each conversations as conversation(conversation.key)}{@const message=conversation.latest}<button class:chosen={selected?.id===message.id||!!message.conversationId&&selected?.conversationId===message.conversationId} class:unread={conversation.unread} class="mail-row" oncontextmenu={e=>context(e,rows.filter(m=>message.conversationId?m.conversationId===message.conversationId:m.id===message.id))} onclick={()=>choose(message)}><span class="mail-row-top"><strong>{addressLabel(message.from)}</strong>{#if message.importance==='high'}<span class="mail-importance" role="img" aria-label="High importance" title="Latest loaded message: high importance"><Flag size={14}/></span>{/if}{#if conversation.hasAttachments}<Paperclip size={13}/>{/if}{#if conversation.unread}<i aria-label="Unread email"></i>{/if}</span><span class="mail-subject">{message.subject||'(No subject)'}</span><small>{message.bodyPreview||'Open message to read'}</small><span class="mail-row-bottom"><time>{mailDate(message)}</time><span title="Messages loaded in this folder or search">{conversation.count} loaded</span></span></button>{/each}
 {#if loading}<p role="status" class="mail-empty">Loading mail…</p>{:else if permitted&&!rows.length&&!error}<p class="mail-empty">{applied?'No matching email.':'No messages in this folder.'}</p>{/if}
 {#if next}<button class="mail-more" disabled={loading} onclick={()=>load(true)}>Load more mail</button>{/if}</div>
 <footer>Refresh to check for new mail. Read-state controls apply to this mailbox. New email sends only after review.</footer></aside>{/if}
 <section class="mail-reader" aria-label="Mail reader"><header class="mail-reader-header">{#if !sidebarOpen}<button aria-label="Show mail sidebar" onclick={()=>onSidebar(true)}><PanelLeftOpen size={19}/></button>{/if}<div><span class="eyebrow">{activeDraft?'YOUR WORDS. YOUR SEND.':selected?'EMAIL CONVERSATION':'LESS NOISE. MORE SIGNAL.'}</span><h2>{activeDraft?(activeDraft.action==='reply'?'Reply':activeDraft.action==='replyAll'?'Reply all':activeDraft.action==='forward'?'Forward':'New email'):selected?.subject|| (selected?'(No subject)':'A little room for your inbox.')}</h2></div>{#if !activeDraft&&selected&&outlookLink(selected.webLink)}<button class="mail-original" onclick={()=>selected&&original(selected)}>Open in Outlook <ArrowUpRight size={15}/></button>{/if}</header>
 {#if readError}<p class="draft-notice" role="alert">{readError}</p>{/if}{#if draftNotice}<p class="draft-notice" role="status">{draftNotice}</p>{/if}
 {#if activeDraft}{#key activeDraft.id}<MailComposer draft={activeDraft} {ownMailAddresses} {ownId} permitted={canSend} onChange={saveDraft} onClose={()=>composing=''} onAccepted={accepted} onDiscard={removeDraft}/>{/key}
 {:else if !isLive}<div class="mail-welcome"><Mail size={48}/><h2>Your mail, with room to breathe.</h2><p>Sign in to Microsoft 365 to connect your mailbox.</p><button class="outline-button" disabled={authBusy} onclick={onSignIn}>Sign in to Microsoft 365</button></div>
 {:else if checking}<div class="mail-welcome" role="status">Checking mailbox access…</div>
 {:else if !permitted}<div class="mail-welcome"><Mail size={48}/><h2>Connect your mailbox</h2><p>Mail preview needs delegated Mail.Read permission and a fresh sign-in. Your chats remain available.</p><button class="outline-button" onclick={onSignIn} disabled={authBusy}>Reconnect for Mail</button></div>
 {:else if !selected}<div class="mail-welcome"><Mail size={48}/><h2>One conversation at a time.</h2><p>Choose an email to read its conversation, or search your mailbox for the person, message or document you need.</p><span>Inbox · Sent mail · Attachments · Mailbox search</span><p class="mail-reading-note">Choose a message to read. Automatic read marking is optional in Settings → Mail.</p></div>
 {:else}<div class="mail-thread" aria-label="Email conversation">
 <p class="mail-reading-note">Sent and received together · unapproved images stay blocked · {readDelay?`Visible messages marked read after ${readDelay} seconds.`:'Automatic marking as read is off.'}</p>
 {#if threadBusy}<p role="status">Loading conversation…</p>{/if}{#if threadError}<p role="alert" class="mail-error">{threadError}<button onclick={()=>loadThread()}>Retry conversation</button></p>{/if}
 <p class="mail-reading-note">{thread.length} {thread.length===1?'message':'messages'} loaded{threadNext?' · More conversation history is available.':''}</p>
 {#each thread as message(message.id)}<article id={'mail-message-'+message.id} class="mail-message" class:mail-selected={message.id===selected.id} oncontextmenu={e=>context(e,[message])}><button class="mail-message-heading" aria-expanded={!!expanded[message.id]} onclick={()=>toggle(message)}><span class="mail-sender-avatar">{addressLabel(message.from)[0]}</span><span><strong>{addressLabel(message.from)}</strong>{#if (bodies[message.id]?.importance??message.importance)==='high'}<span class="mail-importance mail-importance-label"><Flag size={13}/>High importance</span>{/if}{#if direction(message)}<span class="mail-direction">{#if direction(message)==='Sent'}<SentArrow size={12}/>{:else}<ArrowDownLeft size={12}/>{/if}{direction(message)}</span>{/if}<small>{mailDate(message)}</small></span><span class="mail-expand">{expanded[message.id]?'Collapse':'Read message'} <ChevronRight size={16}/></span></button>
 {#if expanded[message.id]}<div class="mail-message-content"><div class="mail-addresses"><div>From: {addressFull(message.from)}</div><div>To: {(bodies[message.id]?.toRecipients??message.toRecipients??[]).map(addressFull).join(', ')||'Recipients unavailable'}</div>{#if bodies[message.id]?.ccRecipients?.length}<div>Cc: {bodies[message.id].ccRecipients!.map(addressFull).join(', ')}</div>{/if}</div>
 {#if bodyBusy[message.id]}<p role="status">Loading message…</p>{:else if bodyError[message.id]}<p role="alert" class="mail-error">{bodyError[message.id]}<button onclick={()=>body(message.id)}>Retry message</button></p>{:else if bodies[message.id]}<div class="mail-response-actions"><button disabled={!canWrite||readBusy} title={canWrite?'Change mailbox read state':'Reconnect for Mail.ReadWrite'} onclick={()=>setRead([message],(bodies[message.id]?.isRead??message.isRead)!==true)}>{(bodies[message.id]?.isRead??message.isRead)===true?'Mark unread':'Mark read'}</button>{#each [['reply','Reply'],['replyAll','Reply all'],['forward','Forward']] as [action,label]}<button onclick={()=>respond(message.id,action as 'reply'|'replyAll'|'forward')}>{label}</button>{/each}</div><MailReadTimer delay={readDelay} enabled={canWrite&&!activeDraft&&focused===message.id&&!readHold[message.id]&&!readBusy&&bodies[message.id]?.isRead===false} onRead={()=>void setRead([message],true)}/><MailBody {defaultPresentation} message={bodies[message.id]} approvedImages={inlineImages[message.id]??{}} onPresentation={plain=>plainMessages[message.id]=plain}/>{#if (bodies[message.id].body?.content?.length??0)>100000}<p class="mail-reading-note">Long message preview may be shortened. Open in Outlook for the complete message.</p>{/if}{/if}
 {#if files[message.id]?.length}<button class="mail-attachment-toggle" disabled={!!fileBusy[message.id]} onclick={()=>attachments(message.id)}><Paperclip size={15}/>{fileBusy[message.id]?'Loading attachments…':'Attachments (including inline files)'}</button>{/if}
 {#if fileError[message.id]}<p class="mail-error" role="alert">{fileError[message.id]}<button onclick={()=>attachments(message.id)}>Check attachments again</button></p>{/if}
 {#if files[message.id]}<div class="mail-attachments">{#each files[message.id] as file(file.id)}<div class="mail-file"><span><strong>{file.name||'Attachment'}</strong><small>{fileSize(file.size??0)}{file.isInline?' · Inline attachment':''}</small></span>{#if canPreviewAttachment(file)}<button disabled={saving} onclick={()=>viewFile(message.id,file)}>Preview</button>{/if}{#if inlineImages[message.id]?.[file.contentId?.replace(/^<|>$/g,'')??'']}<button onclick={()=>blockImage(message.id,file)}>Block again</button>{/if}<button aria-label={`Save ${file.name||'attachment'}`} disabled={saving} onclick={()=>saveFile(message.id,file)}><Download size={15}/><span>Save</span></button></div>{/each}{#if fileNext[message.id]}<button disabled={!!fileBusy[message.id]} onclick={()=>attachments(message.id,true)}>Load more attachments</button>{/if}</div>{/if}
 </div>{/if}</article>{/each}
 {#if threadNext}<button class="mail-more" disabled={threadBusy} onclick={()=>loadThread(true)}>Load more conversation history</button>{/if}
 {#if fileNotice}<p role="status" class="mail-file-notice">{fileNotice}</p>{/if}
 </div>{/if}
 </section>
 {#if detailsOpen&&selected&&!activeDraft}<MailDetails {thread} {bodies} {files} {hashes} {focused} busy={collecting} {saving} errors={Object.fromEntries(thread.map(m=>[m.id,bodyError[m.id]||fileError[m.id]||'']))} more={fileNext} notice={fileNotice} onCollect={()=>void collectMedia()} onMore={id=>void attachments(id,true)} onMessage={id=>void showMessage(id)} onPreview={viewFile} onSave={saveFile} onClose={()=>onDetails(false)} onLink={url=>{const safe=safeMessageLink(url);if(safe)void openUrl(safe).catch(()=>fileNotice='The link could not be opened.');}}/>{/if}
</div>
{#if readMenu}<div use:menuFocus class="read-menu" role="menu" aria-label="Mail read state" style={`left:${readMenu.x}px;top:${readMenu.y}px`}><small>{readMenu.messages.length} loaded {readMenu.messages.length===1?'email':'emails'}</small><button role="menuitem" disabled={!canWrite||readBusy} onclick={()=>readMenu&&setRead(readMenu.messages,true)}>Mark read</button><button role="menuitem" disabled={!canWrite||readBusy} onclick={()=>readMenu&&setRead(readMenu.messages,false)}>Mark unread</button>{#if !canWrite}<small>Reconnect for Mail.ReadWrite</small>{/if}<button role="menuitem" onclick={()=>readMenu=null}>Cancel</button></div>{/if}
<svelte:window onclick={()=>readMenu=null} onkeydown={e=>{if(e.key==='Escape')readMenu=null;}}/>
{#if preview}<div class="mail-preview-backdrop" role="presentation" onclick={e=>{if(e.target===e.currentTarget)preview=null}}><div class="mail-preview" use:previewFocus role="dialog" tabindex="-1" aria-modal="true" aria-label="Mail attachment preview"><header><strong>{preview.name}</strong><button aria-label="Close attachment preview" onclick={()=>preview=null}><X size={20}/></button></header>{#if preview.image}<img src={preview.image} alt={preview.name}/>{:else}<pre>{preview.text}</pre>{/if}</div></div>{/if}
<style>
 .mail-importance{display:inline-flex;align-items:center;gap:5px;color:var(--error);flex:none}.mail-importance-label{font-size:10px;margin-left:10px}

.read-menu{position:fixed;z-index:40;width:240px;padding:8px;border:1px solid var(--border-strong);border-radius:9px;background:var(--surface-panel);box-shadow:0 8px 30px #0005}.read-menu button{display:block;width:100%;text-align:left;padding:9px;border-radius:6px;color:var(--accent)}.read-menu button:hover{background:var(--surface-hover)}.read-menu small{font-size:11px;color:var(--text-secondary)}
.mail-response-actions{display:flex;gap:8px;margin:8px 0 16px}.mail-response-actions button{padding:8px 12px;border:1px solid var(--accent-border);border-radius:7px;color:var(--accent);font-size:12px}

 .mail-compose-actions{display:flex;align-items:center;gap:12px;padding:0 20px 18px}.mail-compose-actions button{padding:9px 14px;border:1px solid var(--accent-border);color:var(--accent);border-radius:7px;font-size:12px}.mail-compose-actions span,.local-drafts{font-size:11px;color:var(--text-secondary)}.local-drafts{padding:12px 4px}.local-drafts summary{cursor:pointer;color:var(--accent)}.draft-notice{padding:12px 24px;margin:0;border-bottom:1px solid var(--accent-border);font-size:12px;line-height:1.7;color:var(--accent)}
 .folder-hint{margin:-6px 20px 16px;font-size:10px;color:var(--text-secondary);line-height:1.5}.mail-direction{display:inline-flex;align-items:center;gap:4px;margin-left:10px;font-size:10px;color:var(--text-secondary)}
 .mail-workspace{position:relative;display:flex;flex:1;min-height:0;min-width:0;height:100%;color:var(--text-primary)}.mail-list{width:340px;max-width:38%;flex:none;background:var(--surface-panel);border-right:1px solid var(--border);display:flex;flex-direction:column;min-height:0}.mail-list>header{display:flex;justify-content:space-between;align-items:center;padding:24px 22px 18px}.mail-list h1{margin:10px 0 0;font-size:28px;letter-spacing:-1px}.mail-list h1 small{font-size:9px;letter-spacing:1px;color:var(--accent);vertical-align:middle;margin-left:8px}.mail-list button:disabled{cursor:wait}.mail-folders{display:flex;gap:8px;padding:0 20px 18px}.mail-folders button{display:flex;gap:8px;align-items:center;border:1px solid var(--border);padding:9px 16px;border-radius:8px;font-size:12px}.mail-folders .chosen{background:var(--accent-soft);border-color:var(--accent-border);color:var(--accent)}.mail-search{margin:0 20px;display:flex;align-items:center;gap:8px;padding:10px 12px;border:1px solid var(--border-strong);background:var(--surface-raised);border-radius:10px}.mail-search input{border:0;background:transparent;color:inherit;min-width:0;flex:1;font-size:12px}.mail-list-heading{display:flex;justify-content:space-between;align-items:center;padding:18px 22px 10px;color:var(--text-secondary);font-size:9px;letter-spacing:1.2px}.mail-rows{overflow:auto;flex:1;padding:0 10px 16px}.mail-row{display:flex;flex-direction:column;text-align:left;width:100%;padding:17px 12px;gap:7px;border:1px solid transparent;border-radius:9px;border-bottom-color:var(--border);margin-bottom:3px}.mail-row.chosen{background:var(--accent-soft);border-color:var(--accent-border)}.mail-row:hover{background:var(--surface-hover)}.mail-row-top{display:flex;gap:7px;align-items:center;width:100%;font-size:12px}.mail-row-top strong{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.mail-row i{height:7px;width:7px;border-radius:50%;background:var(--accent)}.mail-subject{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;width:100%}.mail-row.unread .mail-subject{font-weight:700}.mail-row small{font-size:11px;line-height:1.5;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;color:var(--text-secondary)}.mail-row-bottom{display:flex;justify-content:space-between;gap:8px;width:100%;font-size:10px;color:var(--text-secondary)}.mail-row time{font-size:10px;color:var(--text-secondary)}.mail-list>footer{padding:16px 20px;font-size:10px;color:var(--text-secondary);line-height:1.6;border-top:1px solid var(--border)}.mail-reader{display:flex;flex-direction:column;flex:1;min-width:0;min-height:0;background:var(--surface-base)}.mail-reader-header{display:flex;gap:16px;align-items:center;justify-content:space-between;padding:24px 30px;border-bottom:1px solid var(--border);background:var(--surface-panel);flex:none}.mail-reader-header>div{min-width:0;flex:1}.mail-reader-header h2{margin:10px 0 0;font-size:21px;line-height:1.4;overflow-wrap:anywhere}.mail-original{display:flex;gap:6px;align-items:center;font-size:11px;color:var(--accent);flex:none;padding:9px;border:1px solid var(--accent-border);border-radius:7px}.mail-welcome{margin:auto;text-align:center;padding:40px;max-width:620px;line-height:1.8}.mail-welcome :global(svg){color:var(--accent);margin-bottom:15px}.mail-welcome h2{font-size:30px;letter-spacing:-1px}.mail-welcome p{color:var(--text-secondary);font-size:14px}.mail-welcome>span{color:var(--accent);font-size:11px}.mail-thread{overflow:auto;flex:1;padding:20px clamp(20px,4vw,65px) 40px}.mail-reading-note{font-size:11px;color:var(--text-secondary);line-height:1.6}.mail-message{border:1px solid var(--border);background:var(--surface-raised);border-radius:12px;margin:18px 0;overflow:hidden}.mail-selected{border-color:var(--accent-border)}.mail-message-heading{display:flex;align-items:center;gap:12px;width:100%;padding:17px 20px;text-align:left}.mail-sender-avatar{background:var(--accent-soft);color:var(--accent);height:34px;width:34px;flex:none;border-radius:10px;display:grid;place-items:center;font-weight:700}.mail-message-heading strong{font-size:13px}.mail-message-heading small{display:block;font-size:10px;color:var(--text-secondary);margin-top:5px}.mail-expand{margin-left:auto;color:var(--text-secondary);font-size:10px;display:flex;align-items:center;gap:7px;flex:none}.mail-message-content{padding:0 22px 18px}.mail-addresses{padding:14px 0;border-top:1px solid var(--border);font-size:11px;line-height:1.8;color:var(--text-secondary);overflow-wrap:anywhere}.mail-attachment-toggle{display:flex;gap:8px;align-items:center;color:var(--accent);font-size:11px;padding:10px 0}.mail-file{display:flex;gap:12px;align-items:center;border-top:1px solid var(--border);padding:12px 0;font-size:11px}.mail-file>span{flex:1;min-width:0;overflow-wrap:anywhere}.mail-file small{display:block;margin-top:5px;color:var(--text-secondary)}.mail-file button{display:flex;gap:5px;align-items:center;color:var(--accent);padding:7px;border:1px solid var(--border);border-radius:6px}.mail-error{color:var(--error);font-size:12px;line-height:1.7;padding:12px 20px}.mail-error button{display:block;color:var(--accent);text-decoration:underline;margin-top:8px}.mail-more{display:block;border:1px solid var(--border-strong);padding:10px 16px;margin:18px auto;border-radius:8px;color:var(--accent);font-size:12px}.mail-empty{padding:20px;text-align:center;color:var(--text-secondary);font-size:12px}.mail-search-hint{font-size:11px;padding:8px 20px;color:var(--text-secondary);line-height:1.7}.mail-search-hint button{margin-left:6px;color:var(--accent);text-decoration:underline}.mail-file-notice{padding:15px;border:1px solid var(--accent-border);border-radius:8px;color:var(--accent);font-size:12px;line-height:1.7}.mail-preview-backdrop{position:fixed;inset:0;z-index:30;background:#000a;display:grid;place-items:center;padding:24px}.mail-preview{display:flex;flex-direction:column;max-width:100%;max-height:90dvh;width:900px;background:var(--surface-panel);border:1px solid var(--border-strong);border-radius:12px;overflow:auto}.mail-preview header{display:flex;justify-content:space-between;gap:20px;padding:18px 22px;align-items:center;border-bottom:1px solid var(--border);position:sticky;top:0;background:var(--surface-panel)}.mail-preview pre{padding:20px;overflow:auto;white-space:pre;line-height:1.7;font-size:12px}.mail-preview img{align-self:center;flex:none;width:auto;height:auto;object-fit:contain;max-width:100%;max-height:75dvh}
 @media(max-width:1000px){.mail-list{width:290px}.mail-reader-header{padding:20px}.mail-original{font-size:0;gap:0}.mail-expand{font-size:0}}
</style>
